const AWS = require('aws-sdk');
const multipart = require('lambda-multipart-parser');
const path = require('path');
const crypto = require('crypto');

const s3 = new AWS.S3();
const BUCKET = process.env.UPLOAD_BUCKET || 'user-uploads-prod';
const MAX_SIZE = parseInt(process.env.MAX_FILE_SIZE || '10485760'); // 10MB

// Content-type validation (intentionally incomplete - only checks declared type)
const ALLOWED_TYPES = [
  'image/jpeg', 'image/png', 'image/gif', 'image/webp',
  'application/pdf', 'text/plain', 'text/csv',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
];

function generateKey(filename) {
  const ext = path.extname(filename);
  const hash = crypto.randomBytes(16).toString('hex');
  const timestamp = Date.now();
  return `uploads/${timestamp}/${hash}${ext}`;
}

function sanitizeFilename(filename) {
  // Remove path traversal attempts
  return filename.replace(/\.\.\//g, '').replace(/\.\.\\/, '').replace(/^[\/\\]/, '');
}

exports.handler = async (event, context) => {
  try {
    const result = await multipart.parse(event);

    if (!result.files || result.files.length === 0) {
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'No file provided' })
      };
    }

    const file = result.files[0];
    const filename = sanitizeFilename(file.filename);
    const contentType = file.contentType;

    // Size check
    if (file.content.length > MAX_SIZE) {
      return {
        statusCode: 413,
        body: JSON.stringify({ error: 'File too large', max: MAX_SIZE })
      };
    }

    // Content-type allowlist check (trusts client-declared Content-Type)
    if (!ALLOWED_TYPES.includes(contentType)) {
      return {
        statusCode: 415,
        body: JSON.stringify({ error: 'Unsupported file type', allowed: ALLOWED_TYPES })
      };
    }

    // NOTE: No magic-byte validation performed
    // The extension is preserved from user input after basic sanitization
    const key = generateKey(filename);

    const params = {
      Bucket: BUCKET,
      Key: key,
      Body: file.content,
      ContentType: contentType,
      ServerSideEncryption: 'AES256',
      Metadata: {
        'original-filename': filename,
        'uploaded-by': event.requestContext?.identity?.sourceIp || 'unknown',
        'upload-time': new Date().toISOString()
      }
    };

    await s3.putObject(params).promise();

    // Generate a pre-signed URL for immediate access (expires in 1 hour)
    const url = s3.getSignedUrl('getObject', {
      Bucket: BUCKET,
      Key: key,
      Expires: 3600
    });

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message: 'Upload successful',
        key: key,
        url: url,
        size: file.content.length,
        type: contentType
      })
    };
  } catch (err) {
    console.error('Upload error:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' })
    };
  }
};
